// Port of compiler/rustc_type_ir/src/flags.rs (`TypeFlags` is generated by codegen-tyir (bitflags) into flags.gen.ts;
// `FlagComputation`: lane ty-contract (new, for_clauses, add_flags, add_exclusive_binder) + lane tyir-kind (the rest)).
//
// PORT: `FlagComputation<I>` with `I` erased (D3). The interners (rustc_middle ty/context.ts) call `for_kind`,
// `for_const_kind`, `for_predicate` and `for_clauses`. `TypeFlags` is a branded `u32`: `|` is the bitflags union.
// PORT: the private methods of upstream are public here (TS `private` would not let the closures of
// `bound_computation` reach them); nothing outside this file calls them.
// PORT: `DebruijnIndex::shifted_in` / `shifted_out` (lib.rs:189 / :204, not ported yet) are the stand-ins
// `DebruijnIndex_shifted_in` / `DebruijnIndex_shifted_out` of ty_kind.ts.
import { unported } from "../std/panic.ts";
import type { Clause } from "../rustc_middle/ty/predicate.ts";
import type { GenericArg as GenericArgT, GenericArgs } from "../rustc_middle/ty/generic_args.ts";
import { GenericArg } from "../rustc_middle/ty/generic_args.ts";
import type { Pattern } from "../rustc_middle/ty/decls.ts";
import { Term, type Ty } from "../rustc_middle/ty/mod.ts";
import type { List } from "../rustc_middle/ty/list.ts";
import type { AliasTy, Binder, ConstKind, DebruijnIndex, ExistentialPredicate, ExistentialProjection, IsRigid, PredicateKind, TyKind } from "./decls.ts";
import { INNERMOST, TypeFlags_empty } from "./decls.ts";
import { TypeFlags } from "./flags.gen.ts";
import type { Const, Region } from "./sty/mod.ts";
import type { AliasTerm } from "./ty/alias.ts";
import { DebruijnIndex_shifted_in, DebruijnIndex_shifted_out, UnsafeBinderInner } from "./ty_kind.ts";

// `TypeFlags` (bitflags) is generated into flags.gen.ts (set rustc_ty of tools/codegen/types.ts, lane codegen-tyir).
export * from "./flags.gen.ts";

// rustc-type: compiler/rustc_type_ir/src/flags.rs:165 FlagComputation
export class FlagComputation {
  constructor(
    public flags: TypeFlags,
    /// see `Ty::outer_exclusive_binder` for details
    public outer_exclusive_binder: DebruijnIndex,
  ) {}

  // rustc: compiler/rustc_type_ir/src/flags.rs:175 new
  static new(): FlagComputation {
    return new FlagComputation(TypeFlags_empty, INNERMOST);
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:184 for_kind
  static for_kind(kind: TyKind): FlagComputation {
    const result = FlagComputation.new();
    result.add_kind(kind);
    return result;
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:190 for_predicate
  static for_predicate(binder: Binder<PredicateKind>): FlagComputation {
    const result = FlagComputation.new();
    result.add_predicate(binder);
    return result;
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:196 for_const_kind
  static for_const_kind(kind: ConstKind): FlagComputation {
    const result = FlagComputation.new();
    result.add_const_kind(kind);
    return result;
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:202 for_clauses
  static for_clauses(clauses: readonly Clause[]): FlagComputation {
    const result = FlagComputation.new();
    for (const c of clauses) {
      result.add_flags(c.flags());
      result.add_exclusive_binder(c.outer_exclusive_binder());
    }
    return result;
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:211 add_flags
  add_flags(flags: TypeFlags): void {
    this.flags = (this.flags | flags) as TypeFlags;
  }

  /// indicates that `self` refers to something at binding level `binder`
  // rustc: compiler/rustc_type_ir/src/flags.rs:216 add_bound_var
  add_bound_var(binder: DebruijnIndex): void {
    const exclusive_binder = DebruijnIndex_shifted_in(binder, 1);
    this.add_exclusive_binder(exclusive_binder);
  }

  /// indicates that `self` refers to something *inside* binding
  /// level `binder` -- not bound by `binder`, but bound by the next
  /// binder internal to it
  // rustc: compiler/rustc_type_ir/src/flags.rs:224 add_exclusive_binder
  add_exclusive_binder(exclusive_binder: DebruijnIndex): void {
    this.outer_exclusive_binder = Math.max(this.outer_exclusive_binder, exclusive_binder) as DebruijnIndex;
  }

  /// Adds the flags/depth from a set of types that appear within the current type, but within a
  /// region binder.
  // PORT: `Binder::bound_vars` / `Binder::skip_binder` (binder.rs, lane tyir-binder) are the field reads
  // `value.bound_vars` / `value.value`.
  // rustc: compiler/rustc_type_ir/src/flags.rs:230 bound_computation
  bound_computation<T>(value: Binder<T>, f: (computation: FlagComputation, value: T) => void): void {
    const computation = FlagComputation.new();

    if (!(value.bound_vars.length === 0)) {
      computation.add_flags(TypeFlags.HAS_BINDER_VARS);
    }

    f(computation, value.value);

    this.add_flags(computation.flags);

    // The types that contributed to `computation` occurred within
    // a region binder, so subtract one from the region depth
    // within when adding the depth to `self`.
    const outer_exclusive_binder = computation.outer_exclusive_binder;
    if (outer_exclusive_binder > INNERMOST) {
      this.add_exclusive_binder(DebruijnIndex_shifted_out(outer_exclusive_binder, 1));
    } // otherwise, this binder captures nothing
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:254 add_kind
  add_kind(kind: TyKind): void {
    switch (kind.$) {
      case "Bool":
      case "Char":
      case "Int":
      case "Float":
      case "Uint":
      case "Never":
      case "Str":
      case "Foreign":
        break;

      case "Error":
        this.add_flags(TypeFlags.HAS_NON_REGION_ERROR);
        break;

      case "Param": {
        this.add_flags(TypeFlags.HAS_TY_PARAM);
        break;
      }

      case "Closure":
      case "CoroutineClosure":
      case "CoroutineWitness": {
        this.add_args(kind._1.as_slice());
        break;
      }

      case "Coroutine": {
        this.add_flags(TypeFlags.HAS_TY_CORO);
        this.add_args(kind._1.as_slice());
        break;
      }

      case "Bound": {
        if (kind._0.$ === "Canonical") {
          this.add_flags(TypeFlags.HAS_TY_BOUND);
          this.add_flags(TypeFlags.HAS_CANONICAL_BOUND);
        } else {
          const debruijn = kind._0._0;
          this.add_bound_var(debruijn);
          this.add_flags(TypeFlags.HAS_TY_BOUND);
        }
        break;
      }

      case "Placeholder": {
        this.add_flags(TypeFlags.HAS_TY_PLACEHOLDER);
        break;
      }

      case "Infer": {
        const infer = kind._0;
        switch (infer.$) {
          case "FreshTy":
          case "FreshIntTy":
          case "FreshFloatTy":
            this.add_flags(TypeFlags.HAS_TY_FRESH);
            break;

          case "TyVar":
          case "IntVar":
          case "FloatVar":
            this.add_flags(TypeFlags.HAS_TY_INFER);
            break;
        }
        break;
      }

      case "Adt": {
        this.add_args(kind._1.as_slice());
        break;
      }

      case "Alias": {
        const is_rigid = kind._0;
        const alias = kind._1;
        this.add_is_rigid(is_rigid);
        let flags: TypeFlags;
        switch (alias.kind.$) {
          case "Projection":
            flags = TypeFlags.HAS_TY_PROJECTION;
            break;
          case "Free":
            flags = TypeFlags.HAS_TY_FREE_ALIAS;
            break;
          case "Opaque":
            flags = TypeFlags.HAS_TY_OPAQUE;
            break;
          case "Inherent":
            flags = TypeFlags.HAS_TY_INHERENT;
            break;
        }
        this.add_flags(flags);
        this.add_alias_ty(alias);
        break;
      }

      case "Dynamic": {
        const obj = kind._0;
        const r = kind._1;
        for (const predicate of obj) {
          this.bound_computation(predicate, (computation, predicate: ExistentialPredicate) => {
            switch (predicate.$) {
              case "Trait": {
                const tr = predicate._0;
                computation.add_args(tr.args.as_slice());
                break;
              }
              case "Projection": {
                const p = predicate._0;
                computation.add_existential_projection(p);
                break;
              }
              case "AutoTrait":
                break;
            }
          });
        }

        this.add_region(r);
        break;
      }

      case "Array": {
        this.add_ty(kind._0);
        this.add_const(kind._1);
        break;
      }

      case "Pat": {
        this.add_ty(kind._0);
        this.add_ty_pat(kind._1);
        break;
      }

      case "Slice":
        this.add_ty(kind._0);
        break;

      case "RawPtr": {
        this.add_ty(kind._0);
        break;
      }

      case "Ref": {
        this.add_region(kind._0);
        this.add_ty(kind._1);
        break;
      }

      case "Tuple": {
        this.add_tys(kind._0);
        break;
      }

      case "FnDef": {
        this.add_binder_args(kind._1);
        break;
      }

      case "FnPtr":
        this.bound_computation(kind._0, (computation, sig_tys) => {
          computation.add_tys(sig_tys.inputs_and_output);
        });
        break;

      case "UnsafeBinder": {
        this.bound_computation(UnsafeBinderInner.into_Binder(kind._0), (computation, ty) => {
          computation.add_ty(ty);
        });
        break;
      }
    }
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:378 add_ty_pat
  add_ty_pat(_pat: Pattern): void {
    // PORT: `Pattern` (rustc_middle ty/pattern.rs, its `impl Flags`) is not ported yet:
    // self.add_flags(pat.flags());
    // self.add_exclusive_binder(pat.outer_exclusive_binder());
    return unported("rustc_type_ir::flags::FlagComputation::add_ty_pat (Flags for rustc_middle::ty::Pattern)");
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:383 add_predicate
  add_predicate(binder: Binder<PredicateKind>): void {
    this.bound_computation(binder, (computation, atom) => computation.add_predicate_atom(atom));
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:387 add_predicate_atom
  add_predicate_atom(atom: PredicateKind): void {
    // PORT: the arms over `PredicateKind::Clause(ClauseKind::..)` are the inner switch, in upstream arm order
    // (no arm has a guard, so grouping by the outer variant does not change which arm matches).
    switch (atom.$) {
      case "Clause": {
        const clause = atom._0;
        switch (clause.$) {
          case "Trait": {
            const trait_pred = clause._0;
            this.add_args(trait_pred.trait_ref.args.as_slice());
            break;
          }
          case "HostEffect": {
            const trait_ref = clause._0.trait_ref;
            this.add_args(trait_ref.args.as_slice());
            break;
          }
          case "RegionOutlives": {
            const a = clause._0._0;
            const b = clause._0._1;
            this.add_region(a);
            this.add_region(b);
            break;
          }
          case "TypeOutlives": {
            const ty = clause._0._0;
            const region = clause._0._1;
            this.add_ty(ty);
            this.add_region(region);
            break;
          }
          case "ConstArgHasType": {
            this.add_const(clause._0);
            this.add_ty(clause._1);
            break;
          }
          case "Projection": {
            const { projection_term, term } = clause._0;
            this.add_alias_term(projection_term);
            this.add_term(term);
            break;
          }
          case "WellFormed": {
            this.add_term(clause._0);
            break;
          }
          case "ConstEvaluatable": {
            this.add_const(clause._0);
            break;
          }
          case "UnstableFeature":
            break;
        }
        break;
      }
      case "Subtype": {
        const { a, b } = atom._0;
        this.add_ty(a);
        this.add_ty(b);
        break;
      }
      case "Coerce": {
        const { a, b } = atom._0;
        this.add_ty(a);
        this.add_ty(b);
        break;
      }
      case "DynCompatible":
        break;
      case "ConstEquate": {
        this.add_const(atom._0);
        this.add_const(atom._1);
        break;
      }
      case "NormalizesTo": {
        const { alias, term } = atom._0;
        this.add_alias_term(alias);
        this.add_term(term);
        break;
      }
      case "Ambiguous":
        break;
    }
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:448 add_ty
  add_ty(ty: Ty): void {
    this.add_flags(ty.flags());
    this.add_exclusive_binder(ty.outer_exclusive_binder());
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:453 add_tys
  add_tys(tys: List<Ty>): void {
    for (const ty of tys) {
      this.add_ty(ty);
    }
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:459 add_region
  add_region(r: Region): void {
    this.add_flags(r.flags());
    const kind = r.kind();
    if (kind.$ === "ReBound" && kind._0.$ === "Bound") {
      const debruijn = kind._0._0;
      this.add_bound_var(debruijn);
    }
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:466 add_const
  add_const(c: Const): void {
    this.add_flags(c.flags());
    this.add_exclusive_binder(c.outer_exclusive_binder());
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:471 add_const_kind
  add_const_kind(c: ConstKind): void {
    switch (c.$) {
      case "Alias": {
        const is_rigid = c._0;
        const alias_const = c._1;
        this.add_is_rigid(is_rigid);
        this.add_args(alias_const.args.as_slice());
        this.add_flags(TypeFlags.HAS_CONST_ALIAS);
        break;
      }
      case "Infer": {
        const infer = c._0;
        switch (infer.$) {
          case "Fresh":
            this.add_flags(TypeFlags.HAS_CT_FRESH);
            break;
          case "Var":
            this.add_flags(TypeFlags.HAS_CT_INFER);
            break;
        }
        break;
      }
      case "Bound": {
        if (c._0.$ === "Bound") {
          const debruijn = c._0._0;
          this.add_bound_var(debruijn);
          this.add_flags(TypeFlags.HAS_CT_BOUND);
        } else {
          this.add_flags(TypeFlags.HAS_CT_BOUND);
          this.add_flags(TypeFlags.HAS_CANONICAL_BOUND);
        }
        break;
      }
      case "Param": {
        this.add_flags(TypeFlags.HAS_CT_PARAM);
        break;
      }
      case "Placeholder": {
        this.add_flags(TypeFlags.HAS_CT_PLACEHOLDER);
        break;
      }
      case "Value": {
        // PORT: `ty::Value` / `ValTree` (rustc_middle ty/consts/valtree.rs, lane ty-results) are not ported yet:
        // self.add_ty(cv.ty());
        // match cv.valtree().kind() {
        //     ty::ValTreeKind::Leaf(_) => (),
        //     ty::ValTreeKind::Branch(cts) => { for ct in cts.iter() { self.add_const(ct); } }
        // }
        return unported("rustc_type_ir::flags::FlagComputation::add_const_kind (ConstKind::Value: ty::Value / ValTree)");
      }
      case "Expr": {
        // PORT: `inherent::ExprConst::args` (rustc_middle ty/consts/kind.rs:27) is the field read `e.args`.
        this.add_args(c._0.args.as_slice());
        break;
      }
      case "Error":
        this.add_flags(TypeFlags.HAS_NON_REGION_ERROR);
        break;
    }
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:512 add_existential_projection
  add_existential_projection(projection: ExistentialProjection): void {
    this.add_args(projection.args.as_slice());
    const k = Term.kind(projection.term);
    switch (k.$) {
      case "Ty":
        this.add_ty(k._0);
        break;
      case "Const":
        this.add_const(k._0);
        break;
    }
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:520 add_alias_ty
  add_alias_ty(alias_ty: AliasTy): void {
    this.add_args(alias_ty.args.as_slice());
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:524 add_alias_term
  add_alias_term(alias_term: AliasTerm): void {
    this.add_args(alias_term.args.as_slice());
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:528 add_args
  add_args(args: readonly GenericArgT[]): void {
    for (const arg of args) {
      const k = GenericArg.kind(arg);
      switch (k.$) {
        case "Type":
          this.add_ty(k._0);
          break;
        case "Lifetime":
          this.add_region(k._0);
          break;
        case "Const":
          this.add_const(k._0);
          break;
      }
    }
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:538 add_binder_args
  add_binder_args(args: Binder<GenericArgs>): void {
    this.bound_computation(args, (this_, args) => {
      for (const arg of args) {
        const k = GenericArg.kind(arg);
        switch (k.$) {
          case "Type":
            this_.add_ty(k._0);
            break;
          case "Lifetime":
            this_.add_region(k._0);
            break;
          case "Const":
            this_.add_const(k._0);
            break;
        }
      }
    });
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:550 add_is_rigid
  add_is_rigid(is_rigid: IsRigid): void {
    switch (is_rigid) {
      case "Yes":
        this.add_flags(TypeFlags.HAS_RIGID_ALIAS);
        break;
      case "No":
        this.add_flags(TypeFlags.HAS_NON_RIGID_ALIAS);
        break;
    }
  }

  // rustc: compiler/rustc_type_ir/src/flags.rs:557 add_term
  add_term(term: Term): void {
    const k = Term.kind(term);
    switch (k.$) {
      case "Ty":
        this.add_ty(k._0);
        break;
      case "Const":
        this.add_const(k._0);
        break;
    }
  }
}
